   191  bool SnoopFileReaderDevice::getNextPacket(RawPacket& rawPacket)
   192  {
   193          rawPacket.clear();
   194          if (m_DeviceOpened != true)
   195          {
   196                  PCPP_LOG_ERROR("File device '" << m_FileName << "' not opened");
   197                  return false;
   198          }
   199          snoop_packet_header_t snoop_packet_header;
   200          m_snoopFile.read((char*)&snoop_packet_header, sizeof(snoop_packet_header_t));
   201          if(!m_snoopFile) {
   202                  return false;
   203          }
   204          size_t packetSize = be32toh(snoop_packet_header.included_length);
   205          if(packetSize > 15000) {
   206                  return false;
   207          }
   208          std::unique_ptr<char[]> packetData(new char[packetSize]);
   209          m_snoopFile.read(packetData.get(), packetSize);
   210          if(!m_snoopFile) {
   211                  return false;
   212          }
   213          timespec ts = { static_cast<time_t>(be32toh(snoop_packet_header.time_sec)), static_cast<long>(be32toh(snoop_packet_header.time_usec)) * 1000 };
   214          if (!rawPacket.setRawData((const uint8_t*)packetData.release(), packetSize, ts, static_cast<LinkLayerType>(m_PcapLinkLayerType)))
   215          {
   216                  PCPP_LOG_ERROR("Couldn't set data to raw packet");
   217                  return false;
   218          }
   219          size_t pad = be32toh(snoop_packet_header.packet_record_length) - (sizeof(snoop_packet_header_t) + be32toh(snoop_packet_header.included_length));
   220          m_snoopFile.ignore(pad);
   221          if(!m_snoopFile) {
   222                  return false;
   223          }
   224
   225          m_NumOfPacketsRead++;
   226          return true;
   227  }
